def transform(grid):
    n = len(grid)
    m = len(grid[0]) if n else 0
    # Select a diagonal orientation from repeated same-color diagonal clues;
    # extend each observed stripe periodically across the grid.
    for sign in (1, -1):
        vals = {}
        consistent = True
        for r, row in enumerate(grid):
            for c, v in enumerate(row):
                if v:
                    k = (c + sign * r) % m
                    if k in vals and vals[k] != v:
                        consistent = False
                    vals[k] = v
        if consistent:
            return [[vals.get((c + sign * r) % m, 0) for c in range(m)] for r in range(n)]
    # Otherwise extend complete horizontal rows as a vertical periodic pattern.
    return [grid[r % n][:] for r in range(n)]
